// ** React Imports
import { Fragment } from 'react'

// ** Reactstrap Imports
import { Row, Col, Card, Form, Button, CardBody, CardTitle, CardHeader, FormFeedback } from 'reactstrap'

// ** Third Party Components
import * as yup from 'yup'
import { useForm, Controller } from 'react-hook-form'
import { yupResolver } from '@hookform/resolvers/yup'

// ** Custom Components
import InputPasswordToggle from '@components/input-password-toggle'

// ** Demo Components
import ApiKeysList from './ApiKeysList'
import CreateApiKey from './CreateApikey'
import TwoFactorAuth from './TwoFactorAuth'
import RecentDevices from './RecentDevices'

import axios from 'axios'

const showErrors = (field, valueLen, min) => {
  if (valueLen === 0) {
    return `Vui lòng nhập ${field}`
  } else if (valueLen > 0 && valueLen < min) {
    return `${field} phải có ít nhất ${min} kí tự`
  } else {
    return `Vui lòng nhập ${field}`
  }
}

const defaultValues = {
  new_password: '',
  current_password: '',
  confirm_password: ''
}

const SecurityTabContent = () => {
  const SignupSchema = yup.object().shape({
    current_password: yup
      .string()
      .min(1, obj => showErrors('Mật khẩu hiện tại', obj.value.length, obj.min))
      .required(),
    new_password: yup
      .string()
      .min(8, obj => showErrors('Mật khẩu mới', obj.value.length, obj.min))
      .required(),
    confirm_password: yup
      .string()
      .min(8, obj => showErrors('Xác nhận mật khẩu', obj.value.length, obj.min))
      .required()
      .oneOf([yup.ref(`new_password`), null], 'Mật khẩu phải trùng')
  })
  // ** Hooks
  const {
    control,
    handleSubmit,
    formState: { errors }
  } = useForm({
    defaultValues,
    resolver: yupResolver(SignupSchema)
  })

  const onSubmit = async data => {
    console.log(data)
    if (Object.values(data).every(field => field.length > 0)) {
      const res = await axios.post('/api/v1/user/change-password', data)
      console.log(res)
    } else {
      for (const key in data) {
        if (data[key].length === 0) {
          setError(key, {
            type: 'manual'
          })
        }
      }
    }
  }

  return (
    <Fragment>
      <Card>
        <CardHeader className='border-bottom'>
          <CardTitle tag='h4'>Đổi mật khẩu</CardTitle>
        </CardHeader>
        <CardBody className='pt-1'>
          <Form onSubmit={handleSubmit(onSubmit)}>
            <Row>
              <Col sm='6' className='mb-1'>
                <Controller
                  control={control}
                  id='current_password'
                  name='current_password' 
                  render={({ field }) => (
                    <InputPasswordToggle
                      label='Mật khẩu hiện tại'
                      htmlFor='current_password'
                      className='input-group-merge'
                      invalid={errors.current_password && true}
                      {...field}
                    />
                  )}
                />
                {errors.current_password && <FormFeedback className='d-block'>{errors.current_password.message}</FormFeedback>}
              </Col>
            </Row>
            <Row>
              <Col sm='6' className='mb-1'>
                <Controller
                  control={control}
                  id='new_password'
                  name='new_password'
                  render={({ field }) => (
                    <InputPasswordToggle
                      label='Mật khẩu mới'
                      htmlFor='new_password'
                      className='input-group-merge'
                      invalid={errors.new_password && true}
                      {...field}
                    />
                  )}
                />
                {errors.new_password && <FormFeedback className='d-block'>{errors.new_password.message}</FormFeedback>}
              </Col>
              <Col sm='6' className='mb-1'>
                <Controller
                  control={control}
                  id='confirm_password'
                  name='confirm_password'
                  render={({ field }) => (
                    <InputPasswordToggle
                      label='Xác nhận mật khẩu'
                      htmlFor='confirm_password'
                      className='input-group-merge'
                      invalid={errors.confirm_password && true}
                      {...field}
                    />
                  )}
                />
                {errors.confirm_password && (
                  <FormFeedback className='d-block'>{errors.confirm_password.message}</FormFeedback>
                )}
              </Col>
              <Col xs={12}>
                <p className='fw-bolder'>Yêu cầu:</p>
                <ul className='ps-1 ms-25'>
                  <li className='mb-50'>Ít nhất 8 ký tự</li>
                </ul>
              </Col>
              <Col className='mt-1' sm='12'>
                <Button type='submit' className='me-1' color='primary'>
                  Lưu
                </Button>
                <Button color='secondary' outline>
                  Hủy
                </Button>
              </Col>
            </Row>
          </Form>
        </CardBody>
      </Card>
      {/* <TwoFactorAuth />
      <CreateApiKey />
      <ApiKeysList />
      <RecentDevices /> */}
    </Fragment>
  )
}

export default SecurityTabContent
